// Progression follows existing level, gold and material requirements. Effects stay distinct.
const WEAPON_POWER_ORDER=['tide','ember','briar','frost','silverbrand','storm','cleaver','lunar','eclipse','ravenfang','sunbreaker'];
const WEAPON_BASE_DAMAGE=[25,34,40,50,60,72,90,104,118,134,154];
WEAPON_POWER_ORDER.forEach((id,n)=>{SWORDS[id].base=WEAPON_BASE_DAMAGE[n];SWORDS[id].cd=.7;SWORDS[id].powerTier=n+1});
p.swords=Array.isArray(p.swords)?[...new Set(p.swords.filter(id=>SWORDS[id]))]:['tide'];if(!p.swords.includes('tide'))p.swords.unshift('tide');
if(p.kills>=5&&!p.swords.includes('ember'))p.swords.push('ember');
p.swordUpgrades=Object.assign({tide:p.weapon||0},p.swordUpgrades||{});Object.keys(SWORDS).forEach(id=>p.swordUpgrades[id]=Math.max(0,Math.min(10,Math.floor(Number(p.swordUpgrades[id])||0))));
if(p.sword!==null&&(!p.swords.includes(p.sword)||!SWORDS[p.sword]||p.level<SWORDS[p.sword].level))p.sword='tide';p.weapon=p.sword?p.swordUpgrades[p.sword]:0;p.facing='down';
let weaponEffects=[],attackAngle=0,weaponClock=0,selectedSword=p.sword||'tide';
const UNARMED={name:'Silahsız',base:0,range:0,cd:1,color:'#aaa',edge:'#aaa',level:1,effect:'Çantandan bir kılıç kuşan.'};function equippedSword(){return SWORDS[p.sword]||UNARMED}
function damage(){return equippedSword().base+(p.level-1)*4+p.weapon*7+p.training*3}
function equipSword(id){if(!SWORDS[id]||!p.swords.includes(id)||p.level<SWORDS[id].level||swing>0||activeSwing)return false;p.sword=id;p.weapon=p.swordUpgrades[id]||0;selectedSword=id;save();ui();renderSwordCollection();toast(SWORDS[id].name+' kuşanıldı.');return true}
function unlockSword(id){if(!SWORDS[id]||p.swords.includes(id))return false;p.swords.push(id);log('Yeni kılıç: '+SWORDS[id].name);toast('Yeni kılıç bulundu: '+SWORDS[id].name+' · K ile incele');save();return true}
function forgeSword(id){const s=SWORDS[id];if(!s||p.area!=='hub'||!$('service').open||$('service').dataset.kind!=='smith'||nearestService()?.id!=='smith'||p.swords.includes(id)||p.level<s.level||p.gold<s.cost||p.inventory.ore<s.ore||p.inventory.crystal<s.crystal)return false;p.gold-=s.cost;p.inventory.ore-=s.ore;p.inventory.crystal-=s.crystal;unlockSword(id);ui();save();renderService();return true}
function rollSwordDrop(e){if(p.kills===5)unlockSword('ember');const id={2:'frost',3:'storm',4:'eclipse'}[e.rank];if(id&&rand()<({frost:.08,storm:.05,eclipse:.03}[id]))unlockSword(id)}
function defeatEnemy(e){if(e.dead)return;e.burnTicks=0;e.slow=0;e.dead=7;p.kills++;loot(e);rollSwordDrop(e);let g=Math.round(12*(p.boost==='gold'?1.25:1));p.gold+=g;xp(24);particles.push({x:e.x,y:e.y-45,text:'+'+g+' ALTIN',life:1.2,color:'#f3d387'});log((e.boss?e.name:typeof combatEnemyName==='function'?combatEnemyName(e):creatureName(e.rank))+' yenildi · +'+g+' altın');if(p.kills===5)toast('Görev tamamlandı · Közdiş çantana eklendi! J: görev / K: kılıçlar');if(e.boss)awardBossLoot(e);ui();save()}
function hitEnemy(e,amount,color){if(e.dead)return;e.hp-=amount;e.hit=.16;particles.push({x:e.x,y:e.y-30,text:String(amount),life:.8,color});if(e.hp<=0)defeatEnemy(e)}
function elementalHit(e,id){if(id==='eclipse'){p.hp=Math.min(p.maxHp,p.hp+5);particles.push({x:p.x,y:p.y-107,text:'+5',life:.8,color:'#efa6d0'});ui();save()}if(e.dead)return;if(id==='ember'){e.burnTicks=3;e.burnTimer=.75;}if(id==='frost')e.slow=2;}
function weaponAttack(){if(!p.sword){toast('Saldırmak için bir kılıç kuşan.');return}if(modalOpen()||cooldown>0||activeSwing)return;const s=equippedSword();cooldown=Math.max(.54,s.cd);swing=.54;const close=enemies.filter(e=>!e.dead&&Math.hypot(e.x-p.x,e.y-p.y)<s.range&&(!activeSwing||insideSwordArc(e))).sort((a,b)=>Math.hypot(a.x-p.x,a.y-p.y)-Math.hypot(b.x-p.x,b.y-p.y));attackAngle=close.length?Math.atan2(close[0].y-p.y,close[0].x-p.x):({down:Math.PI/2,up:-Math.PI/2,left:Math.PI,right:0}[p.facing]||0);startSwing();}
function resolveSwordHit(){if(p.area==='hub')return;const s=equippedSword(),close=enemies.filter(e=>!e.dead&&Math.hypot(e.x-p.x,e.y-p.y)<s.range&&(!activeSwing||insideSwordArc(e))).sort((a,b)=>Math.hypot(a.x-p.x,a.y-p.y)-Math.hypot(b.x-p.x,b.y-p.y));tone({tide:260,ember:170,frost:620,storm:850,eclipse:120,briar:330,cleaver:150,lunar:560}[p.sword]||260);
 close.forEach(e=>{hitEnemy(e,damage(),s.color);elementalHit(e,p.sword);let d=Math.hypot(e.x-p.x,e.y-p.y)||1;e.x+=(e.x-p.x)/d*11;e.y+=(e.y-p.y)/d*11;});
 if(p.sword==='storm'&&close.length){const first=close[0],next=enemies.filter(e=>e!==first&&!e.dead&&Math.hypot(e.x-first.x,e.y-first.y)<125).sort((a,b)=>Math.hypot(a.x-first.x,a.y-first.y)-Math.hypot(b.x-first.x,b.y-first.y))[0];if(next){weaponEffects.push({type:'bolt',x:first.x,y:first.y-15,tx:next.x,ty:next.y-15,life:.24,max:.24});hitEnemy(next,14,'#d7c3ff')}}
}
function tickWeapons(dt){weaponClock+=dt;if(modalOpen())return;let dx=Number(!!(keys.d||keys.arrowright))-Number(!!(keys.a||keys.arrowleft)),dy=Number(!!(keys.s||keys.arrowdown))-Number(!!(keys.w||keys.arrowup));if(dx||dy)p.facing=activeSwing?p.facing:Math.abs(dx)>=Math.abs(dy)?(dx>0?'right':'left'):(dy>0?'down':'up');weaponEffects.forEach(f=>f.life-=dt);weaponEffects=weaponEffects.filter(f=>f.life>0);if(p.area==='hub'){cooldown=Math.max(0,cooldown-dt);swing=Math.max(0,swing-dt);return}enemies.forEach(e=>{e.slow=Math.max(0,(e.slow||0)-dt);if(e.dead)return;if(e.burnTicks>0){e.burnTimer-=dt;if(e.burnTimer<=0){e.burnTimer+=.75;e.burnTicks--;hitEnemy(e,4,'#ffb975')}}});}
function drawWeaponEffects(){weaponEffects.forEach(f=>{if(f.type!=='bolt')return;ctx.save();ctx.globalAlpha=f.life/f.max;ctx.strokeStyle='#ede4ff';ctx.lineWidth=2;ctx.beginPath();ctx.moveTo(f.x,f.y);for(let i=1;i<=7;i++){const t=i/7;ctx.lineTo(f.x+(f.tx-f.x)*t+(i%2?7:-7),f.y+(f.ty-f.y)*t+(i%2?-6:6))}ctx.stroke();ctx.restore()});enemies.forEach(e=>{if(e.dead)return;if(e.slow>0){ctx.strokeStyle='#b4edff88';ctx.lineWidth=2;ctx.beginPath();ctx.ellipse(e.x,e.y,22,8,0,0,7);ctx.stroke()}if(e.burnTicks>0)for(let i=0;i<3;i++){const phase=(weaponClock*24+i*9)%25;rect(e.x-10+i*9,e.y-8-phase,3,5,i%2?'#ffdf8a':'#ed9e60')}})}
function swordCatalogHTML(){return '<h3>Boran’ın kılıçları</h3><p class="fine">İlk 5 yaratık ödülü: Közdiş. Diğer kılıçlar daha güçlü bölgelerde düşebilir veya burada üretilebilir. Her kılıcın güçlendirmesi ayrıdır.</p>'+Object.entries(SWORDS).filter(([id])=>id!=='tide').map(([id,s])=>`<div class="shop-row"><span style="color:${s.color}">${s.name}<small>Sv.${s.level} · ${s.cost} ◆ / ${s.ore} cevher / ${s.crystal} kristal</small><small>${s.effect}</small></span><button data-action="forgeSword" data-item="${id}" ${p.swords.includes(id)||p.level<s.level||p.gold<s.cost||p.inventory.ore<s.ore||p.inventory.crystal<s.crystal?'disabled':''}>${p.swords.includes(id)?'Çantanda':p.level<s.level?'Sv.'+s.level+' gerekli':'Üret'}</button></div>`).join('')}
