const oldPersonArt=person;
person=function(x,y,npc=false){if(npc){oldPersonArt(x,y,true);return}const moving=keys.w||keys.a||keys.s||keys.d||keys.arrowup||keys.arrowleft||keys.arrowdown||keys.arrowright,bob=moving?Math.sin(weaponClock*13)*1.6:Math.sin(weaponClock*2)*.5;shadow(x,y,19);const face=p.facing||'down',s=equippedSword();ctx.save();ctx.translate(Math.round(x),Math.round(y+bob));if(face==='up')heldBlade(face);ctx.drawImage(heroSprite(face),-40,-102);if(face!=='up')heldBlade(face);ctx.restore();if(swing>0)drawSlash(x,y,s);};
function heldBlade(face){ctx.save();const side=face==='left'?-1:1;ctx.translate(side*27,-29);let angle=swing>0?attackAngle+Math.PI/2-1.35+(1-swing/.32)*2.7:(face==='left'?-.32:.32);ctx.rotate(angle);blade(ctx,p.sword,p.weapon);ctx.restore();}
function drawSlash(x,y,s){const progress=1-swing/.32,angle=attackAngle-1.7+progress*3.4,r=s.range*.9;ctx.save();ctx.translate(x,y-24);for(let i=0;i<4;i++){ctx.globalAlpha=(1-i*.2)*Math.sin(progress*Math.PI)*.65;ctx.strokeStyle=i?s.color:s.edge;ctx.lineWidth=7-i;ctx.beginPath();ctx.arc(0,0,r-i*4,angle-.95,angle+.12);ctx.stroke()}ctx.globalAlpha=1;for(let i=0;i<s.level+2+Math.floor(p.weapon/3);i++){const a=angle-i*.17,rr=r+Math.sin(i*4+weaponClock*10)*8,xx=Math.cos(a)*rr,yy=Math.sin(a)*rr;rect(xx,yy,3,3,i%2?s.color:s.edge);if(p.sword==='frost'){polygon([[xx,yy-4],[xx+3,yy],[xx,yy+4],[xx-3,yy]],s.edge)}if(p.sword==='storm'){ctx.strokeStyle=s.edge;ctx.lineWidth=1;ctx.beginPath();ctx.moveTo(xx-6,yy-7);ctx.lineTo(xx+2,yy-1);ctx.lineTo(xx-2,yy+2);ctx.lineTo(xx+5,yy+8);ctx.stroke()}}ctx.restore();}
function renderSwordCollection(){if(!$('swordContents'))return;$('swordPreviewName').textContent=SWORDS[selectedSword].name+' · '+SWORDS[selectedSword].effect;$('swordContents').innerHTML=Object.entries(SWORDS).sort(([,a],[,b])=>a.level-b.level||a.base-b.base).map(([id,s])=>{const owned=p.swords.includes(id),equipped=id===p.sword,can=owned&&p.level>=s.level;return `<article class="sword-card ${equipped?'equipped':''}" style="--sword-color:${s.color}"><canvas id="swordIcon-${id}" width="72" height="108" aria-label="${s.name}"></canvas><div><small>SV.${s.level} · ${owned?'ÇANTANDA':'KİLİTLİ'}</small><h3>${s.name}${p.swordUpgrades[id]?' +'+p.swordUpgrades[id]:''}</h3><p>${s.base} temel hasar · Kademe ${s.powerTier}/11 · ${s.effect}</p><p class="fine">${s.description}</p><div class="sword-actions"><button data-equip="${id}" ${!can||equipped?'disabled':''}>${equipped?'Kuşanıldı':!owned?'Boran’da üret':!can?'Sv.'+s.level+' gerekli':'Kuşan'}</button><button data-preview="${id}">Efekti gör</button></div></div></article>`}).join('');$('swordContents').querySelectorAll('[data-equip]').forEach(b=>b.onclick=()=>equipSword(b.dataset.equip));$('swordContents').querySelectorAll('[data-preview]').forEach(b=>b.onclick=()=>{selectedSword=b.dataset.preview;$('swordPreviewName').textContent=SWORDS[selectedSword].name+' · '+SWORDS[selectedSword].effect;$('swords').scrollTop=0;});Object.keys(SWORDS).forEach(id=>{const c=$('swordIcon-'+id);if(c){const g=c.getContext('2d');g.clearRect(0,0,72,108);g.save();g.translate(35,84);blade(g,id,p.swordUpgrades[id]);g.restore()}});}
function drawHeroPreview(){if(!$('character').open&&!$('swords').open)return;const isSword=$('swords').open,c=$(isSword?'swordPreview':'heroPreview');if(!c)return;const g=c.getContext('2d'),id=isSword?selectedSword:p.sword;g.clearRect(0,0,c.width,c.height);g.fillStyle='#192a3c';g.fillRect(0,0,c.width,c.height);g.save();g.translate(c.width/2,c.height-24);g.scale(1.65,1.65);g.fillStyle='#101f31';g.beginPath();g.ellipse(0,0,33,9,0,0,7);g.fill();g.drawImage(heroSprite('down'),-40,-102);g.save();g.translate(27,-29);g.rotate(isSword?.45+Math.sin(weaponClock*1.5)*.16:.28);blade(g,id,p.swordUpgrades[id]);g.restore();g.restore();if(isSword)previewElement(g,id,c.width,c.height);}

function previewElement(g,id,w,h){const s=SWORDS[id],x=w*.77,y=h*.31;g.save();g.globalAlpha=.65+.25*Math.sin(weaponClock*3);if(id==='storm'){g.strokeStyle=s.color;g.lineWidth=1.5;g.beginPath();for(let i=0;i<8;i++){const yy=y-30+i*9,xx=x+Math.sin(i*7+Math.floor(weaponClock*6))*10;i?g.lineTo(xx,yy):g.moveTo(xx,yy)}g.stroke()}else if(id==='eclipse'){g.strokeStyle=s.color;g.lineWidth=2;g.beginPath();g.ellipse(x,y+6,25,42,weaponClock*.4,0,Math.PI*1.65);g.stroke()}else for(let i=0;i<s.level+2;i++){const t=(weaponClock*.4+i*.21)%1,xx=x+Math.sin(i*4+weaponClock)*16,yy=y+35-t*75;g.fillStyle=i%2?s.color:s.edge;if(id==='frost'){g.beginPath();g.moveTo(xx,yy-4);g.lineTo(xx+3,yy);g.lineTo(xx,yy+4);g.lineTo(xx-3,yy);g.fill()}else g.fillRect(xx,yy,id==='ember'?3:2,id==='ember'?5:2)}g.restore()}
